<?php
require_once __DIR__.'/../includes/functions.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';if($a==='save'){$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');if($title===''){flash('Course title is required.');}else{$slug=unique_slug($pdo,'courses',$title,$id?:null);$v=[$title,$slug,trim($_POST['description']??''),trim($_POST['instructor']??''),$_POST['delivery']??'online',(float)($_POST['price']??0),$_POST['status']??'draft'];if($id){$q=$pdo->prepare('UPDATE courses SET title=?,slug=?,description=?,instructor=?,delivery=?,price=?,status=? WHERE id=?');$q->execute([...$v,$id]);flash('Course updated.');}else{$q=$pdo->prepare('INSERT INTO courses(title,slug,description,instructor,delivery,price,status) VALUES(?,?,?,?,?,?,?)');$q->execute($v);flash('Course created.');}}}elseif($a==='delete'){$q=$pdo->prepare('DELETE FROM courses WHERE id=?');$q->execute([(int)$_POST['id']]);flash('Course deleted.');}header('Location: courses.php');exit;}$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM courses WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=$pdo->query('SELECT * FROM courses ORDER BY created_at DESC')->fetchAll();$pageTitle='Academy courses';include __DIR__.'/_header.php';?>
<div class="dash-top"><div><span class="eyebrow">Digital academy</span><h1>Academy courses</h1><p>Create courses and publish them when they are ready for learners.</p></div></div><section class="dash-panel"><h2><?= $edit?'Edit course':'Create a course'?></h2><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Course title<input name="title" required value="<?=e($edit['title']??'')?>"></label><label>Description<textarea name="description" rows="3"><?=e($edit['description']??'')?></textarea></label><div class="form-row"><label>Instructor<input name="instructor" value="<?=e($edit['instructor']??'')?>"></label><label>Delivery<select name="delivery"><?php foreach(['online','physical','hybrid'] as $s):?><option <?=$s===($edit['delivery']??'online')?'selected':''?>><?=$s?></option><?php endforeach;?></select></label></div><div class="form-row"><label>Price (₦)<input type="number" min="0" step="0.01" name="price" value="<?=e($edit['price']??'0')?>"></label><label>Status<select name="status"><?php foreach(['draft','published'] as $s):?><option <?=$s===($edit['status']??'draft')?'selected':''?>><?=$s?></option><?php endforeach;?></select></label></div><button class="btn">Save course</button> <?php if($edit):?><a class="btn btn-outline" href="courses.php">Cancel</a><?php endif;?></form></section><section class="dash-panel"><h2>All courses (<?=count($rows)?>)</h2><div class="table-wrap"><table class="admin-table"><thead><tr><th>Course</th><th>Instructor</th><th>Delivery</th><th>Price</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['title'])?></strong></td><td><?=e($r['instructor'])?></td><td><?=e($r['delivery'])?></td><td>₦<?=number_format((float)$r['price'],2)?></td><td><span class="status status-<?=e($r['status'])?>"><?=e($r['status'])?></span></td><td class="actions"><a href="?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this course?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No courses created yet.</td></tr><?php endif;?></tbody></table></div></section><?php include __DIR__.'/_footer.php';?>